"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[762],{1820(e,n,t){t.r(n),t.d(n,{assets:()=>a,contentTitle:()=>r,default:()=>u,frontMatter:()=>l,metadata:()=>o,toc:()=>d});const o=JSON.parse('{"id":"demos/modal","title":"Singleton Modal with Hook","description":"A flow rendered in a shared singleton modal \u2014 one SequentOutlet at the top of the tree inside a provider. Any component below it opens a flow through a single useModal() hook, with no refs or outlet rendering of its own.","source":"@site/docs/demos/modal.mdx","sourceDirName":"demos","slug":"/demos/modal","permalink":"/react-sequent/dev/docs/demos/modal","draft":false,"unlisted":false,"editUrl":"https://github.com/ganondev/react-sequent/tree/main/docs/docs/demos/modal.mdx","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2,"title":"Singleton Modal with Hook"},"sidebar":"demosSidebar","previous":{"title":"Subsection Flow","permalink":"/react-sequent/dev/docs/demos/subsection-flow"},"next":{"title":"Full-Screen Wizard","permalink":"/react-sequent/dev/docs/demos/wizard"}}');var i=t(4848),s=t(8453);const l={sidebar_position:2,title:"Singleton Modal with Hook"},r="Singleton Modal with Hook",a={},d=[{value:"Sequential Transition",id:"sequential-transition",level:2},{value:"Outlet Reuse",id:"outlet-reuse",level:2}];function c(e){const n={code:"code",h1:"h1",h2:"h2",header:"header",p:"p",pre:"pre",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"singleton-modal-with-hook",children:"Singleton Modal with Hook"})}),"\n",(0,i.jsxs)(n.p,{children:["A flow rendered in a ",(0,i.jsx)(n.strong,{children:"shared singleton modal"})," \u2014 one ",(0,i.jsx)(n.code,{children:"SequentOutlet"})," at the top of the tree inside a provider. Any component below it opens a flow through a single ",(0,i.jsx)(n.code,{children:"useModal()"})," hook, with no refs or outlet rendering of its own."]}),"\n",(0,i.jsxs)(n.p,{children:["Click ",(0,i.jsx)(n.strong,{children:"Open Setup Flow"})," or ",(0,i.jsx)(n.strong,{children:"Report a Bug"})," below \u2014 they're unrelated flows sharing the same outlet."]}),"\n",(0,i.jsx)(n.p,{children:"The example also mixes both step-loader styles: a component loader for the first transition, and direct JSX for the last, which merges the final title into context to update the chrome."}),"\n",(0,i.jsxs)(n.p,{children:["Step changes play a ",(0,i.jsx)(n.strong,{children:"sequential fade-slide transition"})," via the ready-made ",(0,i.jsx)(n.code,{children:"slide({ fade: true })"})," factory from ",(0,i.jsx)(n.code,{children:"react-sequent/transitions"})," \u2014 the outgoing step slides out to the left, then the incoming step slides in from the right."]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-jsx",metastring:"live",live:!0,children:'function SharedModalDemo() {\n  // \u2500\u2500 Modal infrastructure (would live in its own module in a real app) \u2500\u2500\u2500\u2500\u2500\n\n  const ModalContext = React.createContext(null);\n\n  function ModalChrome({ children }) {\n    const { context: ctx, abort } = useSequentContext();\n    return (\n      <div className="demo-modal">\n        <div>\n          <strong>{ctx.title}</strong>\n          <button onClick={() => abort("cancelled")}>\u2715</button>\n        </div>\n        <div>{children}</div>\n      </div>\n    );\n  }\n\n  function ModalProvider({ children }) {\n    const { init, status, result, SequentOutlet } = useSequentFlow();\n\n    return (\n      <ModalContext.Provider value={{ openModal: init, status, result }}>\n        {children}\n        <div style={{ pointerEvents: "auto" }}>\n          <SequentOutlet\n            transition={slide({ fade: true })}\n            chrome={(slot) => (\n              <div className="demo-modal-overlay">\n                <ModalChrome>{slot}</ModalChrome>\n              </div>\n            )}\n          />\n        </div>\n      </ModalContext.Provider>\n    );\n  }\n\n  function useModal() { return React.useContext(ModalContext); }\n\n  // \u2500\u2500 Steps \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  function StepWelcome() {\n    const { advance, abort } = useSequentStep();\n    return (\n      <div>\n        <p>Welcome to the setup flow. This will only take a minute.</p>\n        <div>\n          <button onClick={() => advance(() => StepDetails, { title: "Details" })}>Get Started \u2192</button>\n          <button onClick={() => abort("cancelled")}>Cancel</button>\n        </div>\n      </div>\n    );\n  }\n\n  function StepDetails() {\n    const { retreat, advance, abort, context } = useSequentStep();\n    const [email, setEmail] = useState(context?.email ?? "");\n    return (\n      <div>\n        <p>Fill in your details below.</p>\n        <div>\n          <label>Email:</label>\n          <input\n            type="email"\n            value={email}\n            onChange={(e) => setEmail(e.target.value)}\n            placeholder="you@example.com"\n          />\n        </div>\n        <div>\n          <button onClick={retreat}>\u2190 Back</button>\n          <button onClick={() => advance(() => <StepDone email={email} />, { title: "All done!", email })}>\n            Continue \u2192\n          </button>\n          <button onClick={() => abort("cancelled")}>Cancel</button>\n        </div>\n      </div>\n    );\n  }\n\n  function StepDone({ email }) {\n    const { resolve } = useSequentStep();\n    return (\n      <div>\n        <p>You\'re all set! \ud83c\udf89</p>\n        <p>Thanks {email}</p>\n        <button onClick={() => resolve({ email })}>Close</button>\n      </div>\n    );\n  }\n\n  // \u2500\u2500 A second, unrelated flow \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  function StepBugReport() {\n    const { advance, abort } = useSequentStep();\n    const [description, setDescription] = useState("");\n    return (\n      <div>\n        <p>Describe the issue you encountered.</p>\n        <div>\n          <textarea\n            value={description}\n            onChange={(e) => setDescription(e.target.value)}\n            placeholder="What went wrong?"\n            rows={3}\n          />\n        </div>\n        <div>\n          <button\n            disabled={!description.trim()}\n            onClick={() => advance(() => <StepBugSubmitted description={description} />, { title: "Thanks!", description })}\n          >\n            Submit \u2192\n          </button>\n          <button onClick={() => abort("cancelled")}>Cancel</button>\n        </div>\n      </div>\n    );\n  }\n\n  function StepBugSubmitted({ description }) {\n    const { resolve } = useSequentStep();\n    return (\n      <div>\n        <p>Bug reported!</p>\n        <p>"{description}"</p>\n        <button onClick={() => resolve({ submitted: true, description })}>Close</button>\n      </div>\n    );\n  }\n\n  // \u2500\u2500 Consumers (pure triggers \u2014 no lifecycle awareness) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  function ModalButton({ label, firstStep, ctx }) {\n    const { openModal } = useModal();\n    return (\n      <div className="demo-sandbox">\n        <button onClick={() => openModal(firstStep, ctx)}>{label}</button>\n      </div>\n    );\n  }\n\n  // \u2500\u2500 Flow observer (decoupled from whichever button started the flow) \u2500\u2500\u2500\u2500\u2500\n\n  function FlowLogger() {\n    const { status, result } = useModal();\n    if (status !== "idle") return <p className="demo-log">Flow active \u2014 waiting for result\u2026</p>;\n    if (result?.status === "resolved") return <p className="demo-log">Flow resolved: {JSON.stringify(result.value)}</p>;\n    if (result?.status === "aborted") return <p className="demo-log">Flow aborted.</p>;\n  }\n\n  return (\n    <ModalProvider>\n      <div style={{ display: "flex", gap: "0.5rem" }}>\n        <ModalButton label="Open Setup Flow" firstStep={() => StepWelcome} ctx={{ title: "Welcome" }} />\n        <ModalButton label="Report a Bug" firstStep={() => StepBugReport} ctx={{ title: "Report a Bug" }} />\n      </div>\n      <FlowLogger />\n    </ModalProvider>\n  );\n}\n'})}),"\n",(0,i.jsx)(n.h2,{id:"sequential-transition",children:"Sequential Transition"}),"\n",(0,i.jsxs)(n.p,{children:["The demo uses ",(0,i.jsx)(n.code,{children:"slide({ fade: true })"})," from ",(0,i.jsx)(n.code,{children:"react-sequent/transitions"})," \u2014 its 24px distance and 300ms duration match the hand-rolled harness this demo used to carry. In sequential mode only one step is visible at a time: while ",(0,i.jsx)(n.code,{children:"previousStep"})," is mounted the exit animation plays and its ",(0,i.jsx)(n.code,{children:"onAnimationEnd"})," fires ",(0,i.jsx)(n.code,{children:"onExited"}),"; once the outgoing step unmounts, ",(0,i.jsx)(n.code,{children:"nextStep"})," slides in. ",(0,i.jsx)(n.code,{children:"transitionKey"})," is attached as a React ",(0,i.jsx)(n.code,{children:"key"})," on each animation wrapper so back-to-back queued transitions remount them \u2014 otherwise the CSS animations never restart and ",(0,i.jsx)(n.code,{children:"onExited"})," never fires again."]}),"\n",(0,i.jsx)(n.h2,{id:"outlet-reuse",children:"Outlet Reuse"}),"\n",(0,i.jsxs)(n.p,{children:["Both ",(0,i.jsx)(n.strong,{children:"Setup"})," and ",(0,i.jsx)(n.strong,{children:"Report a Bug"})," are unrelated flows, yet share the same ",(0,i.jsx)(n.code,{children:"ModalProvider"})," and single ",(0,i.jsx)(n.code,{children:"SequentOutlet"}),". Flow state isn't tethered to either button's lifecycle \u2014 each ",(0,i.jsx)(n.code,{children:"openModal()"})," call independently activates the outlet, runs to completion (or cancellation), and returns it to idle, ready for the next flow. No per-flow flags are managed by the provider; the library handles that internally."]})]})}function u(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>l,x:()=>r});var o=t(6540);const i={},s=o.createContext(i);function l(e){const n=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:l(e.components),o.createElement(s.Provider,{value:n},e.children)}}}]);